
const WORDS=[{"id": 0, "w": "堵塞", "p": "dǔsè", "t": "动词", "m": "tắc nghẽn, ngăn chặn", "coll": "交通堵塞、堵塞道路", "s": "早高峰时，这条道路发生堵塞许多车辆只能缓慢前进。"}, {"id": 1, "w": "滞留", "p": "zhìliú", "t": "动词", "m": "ngưng lại, dừng lại", "coll": "滞留机场、旅客滞留", "s": "由于天气原因，部分旅客滞留机场工作人员正在协助安排后续行程。"}, {"id": 2, "w": "折磨", "p": "zhémó", "t": "动词", "m": "giày vò, hành hạ", "coll": "受到折磨、反复折磨", "s": "长期的等待让他备受折磨直到收到消息才终于放下心来。"}, {"id": 3, "w": "翼", "p": "yì", "t": "名词", "m": "cánh, cánh chim", "coll": "机翼、羽翼", "s": "设计师参考鸟的翼的结构尝试改进飞行器的外形。"}, {"id": 4, "w": "担保", "p": "dānbǎo", "t": "动词", "m": "bảo đảm, cam đoan", "coll": "提供担保、为人担保", "s": "签订合同之前，双方对担保的条件进行了详细讨论。"}, {"id": 5, "w": "大体", "p": "dàtǐ", "t": "副词", "m": "đại thể, đại khái, trên cơ bản", "coll": "大体相同、大体了解", "s": "通过这次介绍我们已经大体了解了项目的基本情况。"}, {"id": 6, "w": "勾画", "p": "gōuhuà", "t": "动词", "m": "phác họa, vạch ra, phác thảo", "coll": "勾画蓝图、勾画未来", "s": "这份报告为城市交通的发展勾画了一幅新的蓝图。"}, {"id": 7, "w": "轮廓", "p": "lúnkuò", "t": "名词", "m": "hình dáng, đường nét, nét khái quát", "coll": "清晰的轮廓、建筑轮廓", "s": "晨雾渐渐散去远处建筑的轮廓开始变得清晰起来。"}, {"id": 8, "w": "指责", "p": "zhǐzé", "t": "动词", "m": "chỉ trích, trách móc", "coll": "受到指责、指责别人", "s": "发现问题以后，他没有急于指责别人，而是先核实了具体情况。"}, {"id": 9, "w": "融化", "p": "rónghuà", "t": "动词", "m": "tan ra, chảy ra", "coll": "冰雪融化、逐渐融化", "s": "春天气温回升，山上的冰雪逐渐融化汇成了细小的溪流。"}, {"id": 10, "w": "石油", "p": "shíyóu", "t": "名词", "m": "dầu mỏ, dầu thô", "coll": "石油资源、开采石油", "s": "这份资料介绍了石油资源的分布以及相关产业的发展情况。"}, {"id": 11, "w": "事故", "p": "shìgù", "t": "名词", "m": "tai nạn, sự rủi ro", "coll": "交通事故、避免事故", "s": "前方发生交通事故交警正在引导车辆绕行其他道路。"}, {"id": 12, "w": "割", "p": "gē", "t": "动词", "m": "cắt, bỏ", "coll": "割草、割开绳子", "s": "园丁在草地上割草整理完以后院子显得整齐了许多。"}, {"id": 13, "w": "优胜劣汰", "p": "yōushèng liètài", "t": "成语", "m": "mạnh thắng yếu thua, cá thể thích nghi sẽ được sống sót", "coll": "优胜劣汰、优胜劣汰的机制", "s": "市场竞争中，优胜劣汰的机制促使企业不断改进产品。"}, {"id": 14, "w": "皆", "p": "jiē", "t": "副词", "m": "đều, cũng", "coll": "皆有可能、人人皆知", "s": "这件事早已人人皆知只有他还以为是个秘密。"}, {"id": 15, "w": "明智", "p": "míngzhì", "t": "形容词", "m": "sáng suốt, khôn khéo", "coll": "明智的选择、十分明智", "s": "充分比较以后，再根据实际需求购买才是比较明智的选择。"}, {"id": 16, "w": "出路", "p": "chūlù", "t": "名词", "m": "lối ra, lối thoát", "coll": "寻找出路、新的出路", "s": "面对新的困难，团队没有停留在抱怨中，而是积极寻找出路。"}, {"id": 17, "w": "规范", "p": "guīfàn", "t": "名词／形容词／动词", "m": "quy phạm, chuẩn mực; đúng quy tắc; chuẩn hóa", "coll": "操作规范、规范管理", "s": "工作人员按照统一的操作规范逐项检查设备的运行情况。"}, {"id": 18, "w": "谋求", "p": "móuqiú", "t": "动词", "m": "tìm kiếm, mưu cầu", "coll": "谋求发展、谋求合作", "s": "这家企业通过改进服务积极谋求与更多伙伴合作的机会。"}, {"id": 19, "w": "干预", "p": "gānyù", "t": "动词", "m": "can thiệp", "coll": "人工干预、进行干预", "s": "系统能够处理常见问题，遇到特殊情况时仍然需要人工干预。"}, {"id": 20, "w": "平坦", "p": "píngtǎn", "t": "形容词", "m": "bằng phẳng", "coll": "平坦的道路、地面平坦", "s": "前面是一段平坦的道路大家可以稍微加快脚步。"}, {"id": 21, "w": "奔驰", "p": "bēnchí", "t": "动词", "m": "chạy băng băng, lao nhanh", "coll": "在公路上奔驰、向前奔驰", "s": "列车在广阔的平原上奔驰窗外的景物不断向后退去。"}, {"id": 22, "w": "试图", "p": "shìtú", "t": "动词", "m": "thử, định", "coll": "试图解决、试图解释", "s": "研究人员试图通过新的模型解释观察到的现象。"}, {"id": 23, "w": "引导", "p": "yǐndǎo", "t": "动词", "m": "dẫn đường, dẫn dắt", "coll": "引导方向、引导思考", "s": "好的问题能够引导学生从不同角度思考同一件事。"}, {"id": 24, "w": "串", "p": "chuàn", "t": "量词", "m": "chuỗi, xâu, đoàn, loạt", "coll": "一串珍珠、一串数字", "s": "他在纸上写下一串数字请大家观察其中的规律。"}, {"id": 25, "w": "珍珠", "p": "zhēnzhū", "t": "名词", "m": "hạt trân châu, ngọc trai", "coll": "一颗珍珠、珍珠项链", "s": "这串项链由大小相近的珍珠组成在灯光下显得十分柔和。"}, {"id": 26, "w": "效益", "p": "xiàoyì", "t": "名词", "m": "hiệu quả", "coll": "提高效益、经济效益", "s": "改进生产流程既要考虑经济效益，也应当注意资源的合理利用。"}, {"id": 27, "w": "抵达", "p": "dǐdá", "t": "动词", "m": "đến, tới", "coll": "按时抵达、顺利抵达", "s": "经过几个小时的行驶，客车顺利抵达了目的地。"}, {"id": 28, "w": "终点", "p": "zhōngdiǎn", "t": "名词", "m": "điểm cuối cùng, nơi đến", "coll": "抵达终点、比赛终点", "s": "最后一位选手抵达终点时观众仍然给予了热烈的掌声。"}, {"id": 29, "w": "配备", "p": "pèibèi", "t": "动词", "m": "trang bị", "coll": "配备设备、配备人员", "s": "这辆车配备了新的监测设备用于记录行驶中的相关数据。"}, {"id": 30, "w": "停泊", "p": "tíngbó", "t": "动词", "m": "đỗ, cập bến", "coll": "停泊港口、船只停泊", "s": "夜幕降临，几艘渔船安静地停泊在港口等待第二天出航。"}, {"id": 31, "w": "力求", "p": "lìqiú", "t": "动词", "m": "cố gắng đạt tới, làm hết sức mình", "coll": "力求准确、力求简洁", "s": "撰写说明时，她力求语言简洁让读者容易理解。"}, {"id": 32, "w": "丙", "p": "bǐng", "t": "名词", "m": "Thứ ba/Bính", "coll": "甲乙丙丁、丙组", "s": "参加活动的同学被分成甲、乙、丙三组分别完成不同的任务。"}, {"id": 33, "w": "融合", "p": "rónghé", "t": "动词", "m": "hợp nhất, hòa nhập, hội nhập", "coll": "相互融合、文化融合", "s": "这件作品把传统图案与现代设计相融合形成了独特的风格。"}, {"id": 34, "w": "引擎", "p": "yǐnqíng", "t": "名词", "m": "máy, động cơ", "coll": "汽车引擎、启动引擎", "s": "维修人员打开车盖仔细检查了引擎的运行情况。"}, {"id": 35, "w": "行列", "p": "hángliè", "t": "名词", "m": "hàng ngũ, đội ngũ", "coll": "加入行列、跻身行列", "s": "越来越多的年轻人加入了志愿服务的行列为社区提供实际的帮助。"}, {"id": 36, "w": "潮流", "p": "cháoliú", "t": "名词", "m": "trào lưu, xu hướng", "coll": "时代潮流、顺应潮流", "s": "面对新的潮流，企业需要认真判断哪些变化符合自身的发展方向。"}, {"id": 37, "w": "助理", "p": "zhùlǐ", "t": "名词", "m": "trợ lý", "coll": "担任助理、研究助理", "s": "这位研究助理负责整理资料并协助团队安排访谈时间。"}, {"id": 38, "w": "锦上添花", "p": "jǐnshàng tiānhuā", "t": "成语", "m": "thêu hoa trên gấm, đã hay lại càng hay", "coll": "锦上添花、起到锦上添花的作用", "s": "清晰的图表为这份内容扎实的报告起到了锦上添花的作用。"}, {"id": 39, "w": "保障", "p": "bǎozhàng", "t": "动词", "m": "bảo đảm", "coll": "保障安全、保障权益", "s": "完善服务流程有助于保障顾客的合法权益减少不必要的纠纷。"}, {"id": 40, "w": "丁", "p": "dīng", "t": "名词", "m": "người thứ tư, vật thứ tư", "coll": "甲乙丙丁、丁组", "s": "在这次练习中，丁组负责整理其他三组提出的问题。"}, {"id": 41, "w": "柴油", "p": "cháiyóu", "t": "名词", "m": "dầu diesel", "coll": "柴油发动机、使用柴油", "s": "这份说明书详细介绍了柴油发动机日常维护的要求。"}, {"id": 42, "w": "遏制", "p": "èzhì", "t": "动词", "m": "ngăn chặn, kiềm chế", "coll": "遏制浪费、遏制蔓延", "s": "为了遏制浪费现象，食堂推出了小份菜方便大家按需选择。"}, {"id": 43, "w": "比重", "p": "bǐzhòng", "t": "名词", "m": "tỷ lệ, tỷ trọng", "coll": "所占比重、提高比重", "s": "近年来，公共交通在居民出行方式中所占的比重逐渐提高。"}, {"id": 44, "w": "昂贵", "p": "ángguì", "t": "形容词", "m": "đắt đỏ", "coll": "价格昂贵、费用昂贵", "s": "这套设备虽然功能丰富，但价格昂贵超出了现有预算。"}, {"id": 45, "w": "阻碍", "p": "zǔ'ài", "t": "动词", "m": "ngăn cản, cản trở", "coll": "阻碍发展、受到阻碍", "s": "沟通不畅可能阻碍合作，因此双方决定定期交流进展。"}, {"id": 46, "w": "排除", "p": "páichú", "t": "动词", "m": "loại trừ, loại bỏ", "coll": "排除故障、排除可能性", "s": "维修人员逐一检查相关部件最终排除了设备的故障。"}, {"id": 47, "w": "确保", "p": "quèbǎo", "t": "动词", "m": "bảo đảm", "coll": "确保安全、确保准确", "s": "提交材料之前，请仔细核对确保信息准确。"}, {"id": 48, "w": "排放", "p": "páifàng", "t": "动词", "m": "đổ ra, thải ra", "coll": "减少排放、废气排放", "s": "这项方案希望通过优化运输安排减少车辆行驶产生的废气排放。"}, {"id": 49, "w": "代价", "p": "dàijià", "t": "名词", "m": "giá phải trả, chi phí", "coll": "付出代价、沉重的代价", "s": "忽视产品质量可能让企业付出失去顾客信任的代价。"}, {"id": 50, "w": "伴侣", "p": "bànlǚ", "t": "名词", "m": "bạn đồng hành, đối tác", "coll": "生活伴侣、理想伴侣", "s": "她把书视为生活中的伴侣无论走到哪里都喜欢随身带一本。"}, {"id": 51, "w": "支柱", "p": "zhīzhù", "t": "名词", "m": "chỗ dựa chính, trụ cột", "coll": "精神支柱、经济支柱", "s": "家人的理解与支持始终是他面对困难时重要的精神支柱。"}];
