'use strict';
const root=document.getElementById('ntc-design-preview');
const $=id=>document.getElementById(id);
const STORE='ngocthucac-hsk6-bai22-learning-v3';
const pages=['词汇表','学习生词','词汇卡片','综合练习','连词成句','学习统计'];
let storageOK=true,store={active:null,profiles:{}};
try{let raw=localStorage.getItem(STORE);if(raw){let parsed=JSON.parse(raw);if(parsed&&parsed.profiles)store=parsed}}catch(e){storageOK=false}
let student=store.active?store.profiles[store.active]:null;
if(!student){store.active='local';student=store.profiles.local||createStudent('','');store.profiles.local=student;}
let ui=student?.ui||{page:0,g:0,idx:0,pinyin:false};
let speed=1,playback=null,audioGeneration=0;
const group=g=>WORDS.slice(g*10,g===5?WORDS.length:g*10+10);
const groupOf=id=>Math.min(5,Math.floor(id/10));
const escapeHTML=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#51;'}[c]));
const hasLearned=id=>!!student?.studied.includes(id);
const learned=g=>group(g).filter(d=>hasLearned(d.id)).length;
const allLearned=()=>!!student&&student.studied.length===WORDS.length;
const memory=id=>student?.memory[id]||'new';
const weakIds=()=>WORDS.filter(d=>memory(d.id)==='review').map(d=>d.id);
const totalLearned=()=>student?.studied.length||0;
const currentWord=()=>group(ui.g)[ui.idx];
function gate(){return `<div class="ntc-panel ntc-lock"><div class="ntc-kicker">先学习生词，再进行全课复习</div><h2>请先完成生词学习</h2><p>已学习 ${totalLearned()}/52 个词语。学完6组词语后，即可进行词汇卡片、综合练习和连词成句。</p>${meter(totalLearned(),52)}<div class="ntc-progressgroups">${[0, 1, 2, 3, 4, 5].map(g=>`<button data-group="${g}">组别 ${g+1}<br>${learned(g)}/${group(g).length}个词语</button>`).join('')}</div>${button('继续学习 →','resume','ntc-primary')}</div>`}
function listView(){return `<div class="ntc-panel">${heading('词汇表','全课共52个词语，点击 ↗ 学习该词语',totalLearned()+'/52 已学习')}<div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>汉字</th><th class="ntc-colpinyin">拼音</th><th class="ntc-coltype">词性</th><th>越南语释义</th><th>状态</th></tr></thead><tbody>${WORDS.map((d,i)=>`<tr><td class="ntc-hanzi">${d.w} <button class="ntc-play" data-word="${i}" aria-label="学习词语 ${d.w}">↗</button><button class="ntc-play" data-audio-word="${i}" aria-label="听词语 ${d.w}">◖</button></td><td class="ntc-colpinyin">${escapeHTML(d.p)}</td><td class="ntc-coltype">${escapeHTML(d.t)}</td><td>${escapeHTML(d.m)}</td><td>${status(i)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-actions"><span class="ntc-caption">仅生词学习分为五组：10、10、10、10、7个词语。</span>${button('开始／继续学习 →','resume','ntc-primary')}</div></div>`}
function studyView(){let d=currentWord(),a=group(ui.g),isLast=d.id===51;return `<div class="ntc-panel">${heading('学习生词 · 组别 '+(ui.g+1),'学习词语、搭配与例句',`${ui.idx+1}/${a.length}`)}${meter(learned(ui.g),a.length)}<div class="ntc-study"><div class="ntc-wordbox"><div class="ntc-pinyin" style="visibility:${ui.pinyin?'visible':'hidden'}">${escapeHTML(d.p)}</div><div class="ntc-bigword ntc-writing" id="ntc-writing" aria-label="汉字笔顺">${d.w}</div><div class="ntc-meaning">${escapeHTML(d.m)}</div><span class="ntc-type">${escapeHTML(d.t)}</span><div class="ntc-smallbtns">${button('笔顺演示','strokes')}<button data-audio-word="${d.id}">◖ 听词语</button>${button(ui.pinyin?'隐藏拼音':'显示拼音','pinyin')}</div></div><div><div class="ntc-label">常用搭配</div><div class="ntc-cn">${escapeHTML(d.coll)}</div><hr><div class="ntc-label">例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><div class="ntc-smallbtns"><button data-audio-example="${d.id}">◖ 听例句</button></div><div class="ntc-note">${status(d.id)}</div></div></div><div class="ntc-actions">${button('← 上一个','prev-study','',d.id===0)}${button(isLast?'✓ 已学习 · 全课复习 →':ui.idx===a.length-1?'✓ 已学习 · 下一组 →':'✓ 已学习 · 下一个 →','mark-study','ntc-primary')}</div><div class="ntc-footnote">点击“已学习”记录学习进度。需要时，可点击“笔顺演示”查看汉字的书写顺序。</div></div>`}
function markStudy(){let d=currentWord();if(!student.studied.includes(d.id))student.studied.push(d.id);let next=WORDS.find(x=>!student.studied.includes(x.id));if(d.id<51){let id=d.id+1;ui.g=groupOf(id);ui.idx=id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx}}else if(!next){ui.page=2;student.bookmark={g:5,idx:1};if(!student.flash)startFlash('all',false)}else{ui.g=groupOf(next.id);ui.idx=next.id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx};toast('还有未学完的词语，请继续学习。')}save();render()}
function flashView(){let f=student.flash;if(f.done)f.done=false;let d=WORDS[f.ids[f.at]];return `<div class="ntc-panel">${heading('词汇卡片 · 全课复习',f.filter==='weak'?'复习练习中答错的词语':'全课52个词语随机排列，不分组',`${f.at+1}/${f.ids.length}`)}${meter(f.at+1,f.ids.length)}<div class="ntc-smallbtns" style="margin-bottom:16px">${button('重新打乱全课52个词语','flash-all')}${button('待复习词语 ('+weakIds().length+')','flash-weak','',!weakIds().length)}</div><div class="ntc-flash"><span class="ntc-label">${f.flipped?'背面':'正面'}</span>${f.flipped?`<span class="ntc-pinyin">${escapeHTML(d.p)}</span><span class="ntc-meaning">${escapeHTML(d.m)}</span><span class="ntc-type">${escapeHTML(d.t)}</span><small>${escapeHTML(d.coll)}</small><div class="ntc-note"><span class="ntc-cn">${escapeHTML(d.s)}</span><button class="ntc-play" data-audio-example="${d.id}" aria-label="听例句">◖</button></div>`:`<div style="display:flex;align-items:center;justify-content:center;gap:12px"><span class="ntc-bigword" style="font-size:clamp(51px,${d.w.length>2?'7':'10'}vw,${d.w.length>2?'80':'112'}px)">${d.w}</span><button class="ntc-play" data-audio-word="${d.id}" aria-label="听发音 ${d.w}" title="听发音">🔊</button></div>`}<div class="ntc-smallbtns">${button(f.flipped?'↶ 返回正面':'查看释义与例句 ↻','flip')}</div></div><div class="ntc-actions">${button('← 上一张','flash-prev','',f.at===0)}${f.at===f.ids.length-1?button('综合练习 →','quiz-page','ntc-primary'):button('下一张 →','flash-next','ntc-primary')}</div><div class="ntc-footnote">先看正面回忆词义；需要时翻到背面查看拼音、释义与例句。无需翻面即可切换卡片。</div></div>`}
const contextAlternatives={"2": [3, 10, 25], "5": [3, 10, 25], "8": [3, 10, 25], "11": [3, 10, 25], "14": [3, 10, 25], "17": [3, 10, 25], "20": [3, 10, 25], "23": [3, 10, 25], "26": [0, 1, 2], "29": [3, 10, 25], "32": [3, 10, 25], "35": [0, 1, 2], "38": [3, 10, 25], "41": [3, 10, 25], "44": [3, 10, 25], "47": [3, 10, 25], "50": [0, 1, 2]};
function orderView(){let o=student.order;if(o.done)return orderResults();let id=o.ids[o.at],d=WORDS[id],chunks=CHUNKS[id],ok=o.selected.every((x,i)=>x===i);return `<div class="ntc-panel">${heading('连词成句 · 全课复习','使用已学的52个例句，题目随机排列',`${o.at+1}/${o.ids.length}题`)}${meter(o.at,o.ids.length)}<div class="ntc-label">重点词语 · ${d.w}</div><p class="ntc-caption">按顺序选择词语，点击已选词语可将其放回。</p><div class="ntc-orderanswer ${o.checked?(ok?'ntc-correct':'ntc-wrong'):''}" aria-label="已排列的句子">${o.selected.length?o.selected.map((index,i)=>`<button data-remove="${i}" ${o.checked?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join(''):'<span class="ntc-caption">请在这里排列句子……</span>'}</div><div class="ntc-chunks" aria-label="待选词语">${o.bank.map(index=>`<button class="${o.selected.includes(index)?'used':''}" data-chunk="${index}" ${o.checked||o.selected.includes(index)?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join('')}</div><div class="ntc-actions"><div class="ntc-smallbtns">${button('↶ 撤销最后一项','order-undo','',!o.selected.length||o.checked)}${button('重新排列','order-clear','',!o.selected.length||o.checked)}</div>${button('检查答案','order-check','ntc-primary',o.selected.length!==chunks.length||o.checked)}</div>${o.checked?`<div class="ntc-note" role="status"><strong>${ok?'✓ 与例句顺序一致':'✕ 与例句顺序不一致'}</strong><div class="ntc-label">原例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><button data-audio-example="${id}">◖ 听例句</button></div><div class="ntc-actions"><span></span>${button(o.at===o.ids.length-1?'查看结果 →':'下一题 →','order-next','ntc-primary')}</div>`:''}<div class="ntc-footnote">本练习按原例句顺序评分，其他语序也可能符合语法。</div></div>`}
function orderResults(){let o=student.order,wrong=o.answers.filter(x=>!x.ok).map(x=>x.id),correct=o.answers.length-wrong.length;return `<div class="ntc-panel">${heading('连词成句结果','第22课综合复习')}<div class="ntc-score">${correct}<small> / ${o.answers.length}题答对</small></div><div class="ntc-tag">${wrong.length} 题需要重新练习</div>${wrong.map(id=>`<div class="ntc-miniresult"><strong>${WORDS[id].w}</strong><br><span class="ntc-cn">${escapeHTML(WORDS[id].s)}</span></div>`).join('')}<div class="ntc-actions">${button('重新练习全课句子','order-restart')}${button('重练错题','order-retry','',!wrong.length)}${button('查看学习统计 →','stats-page','ntc-primary')}</div></div>`}
function statsView(){let weak=weakIds();return `<div class="ntc-panel">${heading('学习统计','当前浏览器中的第22课学习进度','第22课 · 52个词语')}<div class="ntc-statrow"><div class="ntc-stat"><label>已学词语</label><strong>${totalLearned()}<small> / 52</small></strong></div><div class="ntc-stat"><label>需要复习</label><strong>${weak.length}<small>个词语</small></strong></div></div><div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>组别</th><th>已学习</th><th>待复习</th><th>综合练习</th><th>连词成句</th></tr></thead><tbody>${[0, 1, 2, 3, 4, 5].map(g=>`<tr><td>组别 ${g+1}<div class="ntc-caption">${group(g).length}个词语</div></td><td>${learned(g)}/${group(g).length}</td><td>${group(g).filter(d=>memory(d.id)==='review').length}</td><td>${activityScore('quiz',g)}</td><td>${activityScore('order',g)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-footnote">按词语所属组显示答对题数／已答题数。优先显示本轮进度，否则显示最近一轮结果。</div><hr><div class="ntc-sectionhead"><h2>待复习词语</h2>${button('用词汇卡片复习 →','flash-weak','',!weak.length||!allLearned())}</div><div class="ntc-terms">${weak.length?weak.map(id=>`<button data-word="${id}">${WORDS[id].w}</button>`).join(''):'<span class="ntc-caption">暂无需要复习的错词。</span>'}</div><div class="ntc-note">继续学习：组别 ${student.bookmark.g+1} · 词语 ${student.bookmark.idx+1}/${group(student.bookmark.g).length}.<br>本页累计学习时间约 ${Math.floor(student.timeMs/60000)} 分钟。已完成综合练习轮数： ${student.quizHistory.length}; 连词成句轮数： ${student.orderHistory.length}.</div><div class="ntc-actions">${button('继续学习','resume','ntc-primary')}${button('导出学习记录','backup')}${button('恢复学习记录','restore')}</div><div class="ntc-footnote">答错词语会列入待复习词语。浏览词汇卡片不等于掌握词语。</div></div>`}
function render(){clearWriting();let total=totalLearned();$('ntc-profile-button').textContent='HSK6 · 第22课';$('ntc-bookmark').textContent=student?total+'/52 个已学词语':'';$('ntc-tabs').innerHTML=pages.map((name,i)=>`<button class="ntc-tab ${ui.page===i?'active':''}" data-page="${i}" aria-pressed="${ui.page===i}">${i<5?i+1+'. ':''}${name}${i>=2&&i<=4&&!allLearned()?' 🔒':''}</button>`).join('');let showGroups=ui.page===1;$('ntc-groups').hidden=!showGroups;$('ntc-groups').innerHTML=showGroups?[0, 1, 2, 3, 4, 5].map(g=>`<button data-group="${g}" class="${g===ui.g?'active':''}">组别 ${g+1} · ${group(g).length}个词语 · ${learned(g)}/${group(g).length}</button>`).join(''):'';$('ntc-sidegroups').innerHTML=showGroups?'<div class="ntc-navtitle">当前词汇组</div>'+[0, 1, 2, 3, 4, 5].map(g=>`<button class="ntc-sidegroup ${g===ui.g?'active':''}" data-group="${g}"><span>组别 ${g+1}<br><small>词语 ${g*10+1}–${g*10+group(g).length}</small></span><small>${learned(g)}/${group(g).length}</small></button>`).join(''):'<div class="ntc-navtitle">第22课学习进度</div><div style="padding:0 10px">'+total+'/52 个已学词语'+meter(total,52)+'</div>';$('ntc-sidefoot').innerHTML='学完生词 →<br>全课综合复习。<br><br>进度保存在<br>当前浏览器中。';let html;if(ui.page>=2&&ui.page<=4&&!allLearned())html=gate();else html=[listView,studyView,flashView,quizView,orderView,statsView][ui.page]();$('ntc-view').innerHTML=html;if(ui.page===1)setupWriting();}
const AUDIO_INDEX={"堵塞":"data:audio/mpeg;base64,","早高峰时，这条道路发生堵塞许多车辆只能缓慢前进。":"data:audio/mpeg;base64,","滞留":"data:audio/mpeg;base64,","由于天气原因，部分旅客滞留机场工作人员正在协助安排后续行程。":"data:audio/mpeg;base64,","折磨":"data:audio/mpeg;base64,","长期的等待让他备受折磨直到收到消息才终于放下心来。":"data:audio/mpeg;base64,","翼":"data:audio/mpeg;base64,","设计师参考鸟的翼的结构尝试改进飞行器的外形。":"data:audio/mpeg;base64,","担保":"data:audio/mpeg;base64,","签订合同之前，双方对担保的条件进行了详细讨论。":"data:audio/mpeg;base64,","大体":"data:audio/mpeg;base64,","通过这次介绍我们已经大体了解了项目的基本情况。":"data:audio/mpeg;base64,","勾画":"data:audio/mpeg;base64,","这份报告为城市交通的发展勾画了一幅新的蓝图。":"data:audio/mpeg;base64,","轮廓":"data:audio/mpeg;base64,","晨雾渐渐散去远处建筑的轮廓开始变得清晰起来。":"data:audio/mpeg;base64,","指责":"data:audio/mpeg;base64,","发现问题以后，他没有急于指责别人，而是先核实了具体情况。":"data:audio/mpeg;base64,","融化":"data:audio/mpeg;base64,","春天气温回升，山上的冰雪逐渐融化汇成了细小的溪流。":"data:audio/mpeg;base64,","石油":"data:audio/mpeg;base64,","这份资料介绍了石油资源的分布以及相关产业的发展情况。":"data:audio/mpeg;base64,","事故":"data:audio/mpeg;base64,","前方发生交通事故交警正在引导车辆绕行其他道路。":"data:audio/mpeg;base64,","割":"data:audio/mpeg;base64,","园丁在草地上割草整理完以后院子显得整齐了许多。":"data:audio/mpeg;base64,","优胜劣汰":"data:audio/mpeg;base64,","市场竞争中，优胜劣汰的机制促使企业不断改进产品。":"data:audio/mpeg;base64,","皆":"data:audio/mpeg;base64,","这件事早已人人皆知只有他还以为是个秘密。":"data:audio/mpeg;base64,","明智":"data:audio/mpeg;base64,","充分比较以后，再根据实际需求购买才是比较明智的选择。":"data:audio/mpeg;base64,","出路":"data:audio/mpeg;base64,","面对新的困难，团队没有停留在抱怨中，而是积极寻找出路。":"data:audio/mpeg;base64,","规范":"data:audio/mpeg;base64,","工作人员按照统一的操作规范逐项检查设备的运行情况。":"data:audio/mpeg;base64,","谋求":"data:audio/mpeg;base64,","这家企业通过改进服务积极谋求与更多伙伴合作的机会。":"data:audio/mpeg;base64,","干预":"data:audio/mpeg;base64,","系统能够处理常见问题，遇到特殊情况时仍然需要人工干预。":"data:audio/mpeg;base64,","平坦":"data:audio/mpeg;base64,","前面是一段平坦的道路大家可以稍微加快脚步。":"data:audio/mpeg;base64,","奔驰":"data:audio/mpeg;base64,","列车在广阔的平原上奔驰窗外的景物不断向后退去。":"data:audio/mpeg;base64,","试图":"data:audio/mpeg;base64,","研究人员试图通过新的模型解释观察到的现象。":"data:audio/mpeg;base64,","引导":"data:audio/mpeg;base64,","好的问题能够引导学生从不同角度思考同一件事。":"data:audio/mpeg;base64,","串":"data:audio/mpeg;base64,","他在纸上写下一串数字请大家观察其中的规律。":"data:audio/mpeg;base64,","珍珠":"data:audio/mpeg;base64,","这串项链由大小相近的珍珠组成在灯光下显得十分柔和。":"data:audio/mpeg;base64,","效益":"data:audio/mpeg;base64,","改进生产流程既要考虑经济效益，也应当注意资源的合理利用。":"data:audio/mpeg;base64,","抵达":"data:audio/mpeg;base64,","经过几个小时的行驶，客车顺利抵达了目的地。":"data:audio/mpeg;base64,","终点":"data:audio/mpeg;base64,","最后一位选手抵达终点时观众仍然给予了热烈的掌声。":"data:audio/mpeg;base64,","配备":"data:audio/mpeg;base64,","这辆车配备了新的监测设备用于记录行驶中的相关数据。":"data:audio/mpeg;base64,","停泊":"data:audio/mpeg;base64,","夜幕降临，几艘渔船安静地停泊在港口等待第二天出航。":"data:audio/mpeg;base64,","力求":"data:audio/mpeg;base64,","撰写说明时，她力求语言简洁让读者容易理解。":"data:audio/mpeg;base64,","丙":"data:audio/mpeg;base64,","参加活动的同学被分成甲、乙、丙三组分别完成不同的任务。":"data:audio/mpeg;base64,","融合":"data:audio/mpeg;base64,","这件作品把传统图案与现代设计相融合形成了独特的风格。":"data:audio/mpeg;base64,","引擎":"data:audio/mpeg;base64,","维修人员打开车盖仔细检查了引擎的运行情况。":"data:audio/mpeg;base64,","行列":"data:audio/mpeg;base64,","越来越多的年轻人加入了志愿服务的行列为社区提供实际的帮助。":"data:audio/mpeg;base64,","潮流":"data:audio/mpeg;base64,","面对新的潮流，企业需要认真判断哪些变化符合自身的发展方向。":"data:audio/mpeg;base64,","助理":"data:audio/mpeg;base64,","这位研究助理负责整理资料并协助团队安排访谈时间。":"data:audio/mpeg;base64,","锦上添花":"data:audio/mpeg;base64,","清晰的图表为这份内容扎实的报告起到了锦上添花的作用。":"data:audio/mpeg;base64,","保障":"data:audio/mpeg;base64,","完善服务流程有助于保障顾客的合法权益减少不必要的纠纷。":"data:audio/mpeg;base64,","丁":"data:audio/mpeg;base64,","在这次练习中，丁组负责整理其他三组提出的问题。":"data:audio/mpeg;base64,","柴油":"data:audio/mpeg;base64,","这份说明书详细介绍了柴油发动机日常维护的要求。":"data:audio/mpeg;base64,","遏制":"data:audio/mpeg;base64,","为了遏制浪费现象，食堂推出了小份菜方便大家按需选择。":"data:audio/mpeg;base64,","比重":"data:audio/mpeg;base64,","近年来，公共交通在居民出行方式中所占的比重逐渐提高。":"data:audio/mpeg;base64,","昂贵":"data:audio/mpeg;base64,","这套设备虽然功能丰富，但价格昂贵超出了现有预算。":"data:audio/mpeg;base64,","阻碍":"data:audio/mpeg;base64,","沟通不畅可能阻碍合作，因此双方决定定期交流进展。":"data:audio/mpeg;base64,","排除":"data:audio/mpeg;base64,","维修人员逐一检查相关部件最终排除了设备的故障。":"data:audio/mpeg;base64,","确保":"data:audio/mpeg;base64,","提交材料之前，请仔细核对确保信息准确。":"data:audio/mpeg;base64,","排放":"data:audio/mpeg;base64,","这项方案希望通过优化运输安排减少车辆行驶产生的废气排放。":"data:audio/mpeg;base64,","代价":"data:audio/mpeg;base64,","忽视产品质量可能让企业付出失去顾客信任的代价。":"data:audio/mpeg;base64,","伴侣":"data:audio/mpeg;base64,","她把书视为生活中的伴侣无论走到哪里都喜欢随身带一本。":"data:audio/mpeg;base64,","支柱":"data:audio/mpeg;base64,","家人的理解与支持始终是他面对困难时重要的精神支柱。":"data:audio/mpeg;base64,"};
function backup(){const content=JSON.stringify({format:'ntc-hsk6-bai22-v3',profile:student},null,2);let url=URL.createObjectURL(new Blob([content],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='HSK6_Bai22_TienDo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function restore(){let input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.addEventListener('change',async()=>{try{let v=JSON.parse(await input.files[0].text()),p=v.profile;if(v.format!=='ntc-hsk6-bai22-v3'||!p||typeof p.name!=='string'||typeof p.clas!=='string'||!Array.isArray(p.studied)||p.studied.some(id=>!Number.isInteger(id)||id<0||id>=52)||!p.memory)throw Error();if(!confirm('恢复第22课学习记录？当前记录将被替换。'))return;let id=store.active||'local';let clean=createStudent(p.name,p.clas);clean.studied=[...new Set(p.studied)];for(let k=0;k<52;k++)if(['remembered','review'].includes(p.memory[k]))clean.memory[k]=p.memory[k];if(p.bookmark&&Number.isInteger(p.bookmark.g)&&p.bookmark.g>=0&&p.bookmark.g<6&&Number.isInteger(p.bookmark.idx)&&p.bookmark.idx>=0&&p.bookmark.idx<group(p.bookmark.g).length)clean.bookmark=p.bookmark;for(let key of ['quizHistory','orderHistory'])if(Array.isArray(p[key]))clean[key]=p[key].filter(r=>r&&Array.isArray(r.answers)&&r.answers.every(a=>Number.isInteger(a.id)&&a.id>=0&&a.id<52&&typeof a.ok==='boolean'));clean.timeMs=Math.max(0,Number(p.timeMs)||0);store.profiles[id]=clean;store.active=id;student=clean;ui={page:5,g:0,idx:0,pinyin:false};save();render();toast('已恢复已学词语、复习状态与练习记录。')}catch(e){toast('无法读取有效的HSK6第22课学习记录。')}});input.click()}
root.addEventListener('click',event=>{let b=event.target.closest('button');if(!b||b.disabled)return;const data=b.dataset;if(data.audioWord!==undefined){speak(WORDS[+data.audioWord].w);return}if(data.audioExample!==undefined){speak(WORDS[+data.audioExample].s);return}if(data.page!==undefined){go(+data.page);return}if(data.group!==undefined){chooseGroup(+data.group);return}if(data.word!==undefined){let id=+data.word;ui.g=groupOf(id);ui.idx=id-ui.g*10;go(1);return}if(data.answer!==undefined){stopAudio();pickQuiz(+data.answer);return}if(data.chunk!==undefined){addChunk(+data.chunk);return}if(data.remove!==undefined){removeChunk(+data.remove);return}let a=data.action;if(!a)return;if(a==='stop'){stopAudio();return}switch(a){case'strokes':animateWriting();return;case'resume':ui.g=student.bookmark.g;ui.idx=student.bookmark.idx;go(1);return;case'pinyin':ui.pinyin=!ui.pinyin;break;case'prev-study':{let id=currentWord().id-1;ui.g=groupOf(id);ui.idx=id-ui.g*10;break}case'mark-study':stopAudio();markStudy();return;case'flip':student.flash.flipped=!student.flash.flipped;break;case'flash-all':if(!allLearned()){go(2);return}ui.page=2;startFlash('all');return;case'flash-weak':if(!allLearned()){go(2);return}ui.page=2;startFlash('weak');return;case'flash-prev':student.flash.at--;student.flash.flipped=false;break;case'flash-next':student.flash.at++;student.flash.flipped=false;break;case'quiz-page':go(3);return;case'order-page':go(4);return;case'stats-page':go(5);return;case'quiz-as-meaning':student.quiz.questions[student.quiz.at].type='meaning';break;case'quiz-next':stopAudio();nextQuiz();return;case'quiz-restart':startQuiz();return;case'quiz-retry':startQuiz(true,student.quiz.questions.filter(x=>x.picked!==x.correct).map(x=>x.id));return;case'order-undo':removeChunk(student.order.selected.length-1);return;case'order-clear':student.order.selected=[];break;case'order-check':checkOrder();return;case'order-next':stopAudio();nextOrder();return;case'order-restart':startOrder();return;case'order-retry':startOrder(student.order.answers.filter(x=>!x.ok).map(x=>x.id));return;case'backup':backup();return;case'restore':restore();return;default:return}save();render()});
root.addEventListener('change',event=>{if(event.target.id==='ntc-rate')speed=Number(event.target.value)});


let strokeWriters=[],strokeRun=0;
async function animateWriting(){const token=++strokeRun,list=[...strokeWriters];if(!list.length){toast('暂时无法显示笔顺。');return;}const button=root.querySelector('[data-action="strokes"]');if(button)button.disabled=true;try{for(const w of list)await w.hideCharacter({duration:0});for(const w of list){if(token!==strokeRun)return;await w.animateCharacter();}}finally{if(token===strokeRun&&button)button.disabled=false;}}

let lastTick=Date.now();setInterval(()=>{let now=Date.now();if(student&&!document.hidden){student.timeMs+=Math.min(now-lastTick,15000);save()}lastTick=now},15000);
window.addEventListener('pagehide',()=>{save();stopAudio()});
if(student&&ui.page>=2&&ui.page<=4&&allLearned()){if(ui.page===2&&!student.flash)startFlash('all',false);if(ui.page===3&&!student.quiz)startQuiz(false);if(ui.page===4&&!student.order)startOrder(null,false)}
save();render();if(!storageOK)toast('浏览器阻止保存数据，建议导出学习记录作为备份。');

